import json
from openai import OpenAI

client = OpenAI()

def get_weather(city: str) -> dict:
    # Your real implementation here
    return {"temp_c": 18, "condition": "cloudy"}

tools = [{
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "Get current weather for a city",
        "parameters": {
            "type": "object",
            "properties": {"city": {"type": "string"}},
            "required": ["city"],
            "additionalProperties": False
        },
        "strict": True
    }
}]

messages = [
    {"role": "system", "content": "You have access to get_weather. Use it when users ask for weather."},
    {"role": "user", "content": "What's the weather in Tokyo?"}
]

# 1. REASON
response = client.chat.completions.create(
    model="gpt-4o-mini",
    messages=messages,
    tools=tools,
    tool_choice="auto"
)
msg = response.choices[0].message
messages.append(msg.model_dump())

# 2. ACT (if tool calls exist)
if msg.tool_calls:
    for tc in msg.tool_calls:
        args = json.loads(tc.function.arguments)
        result = get_weather(**args)
        # 3. OBSERVE
        messages.append({
            "role": "tool",
            "tool_call_id": tc.id,
            "name": tc.function.name,
            "content": json.dumps(result)
        })
    # 4. REASON again → final answer
    final = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=messages,
        tools=tools
    )
    print(final.choices[0].message.content)  # "It's 18°C and cloudy in Tokyo."
